-- 포스터 글은 사진 글자 읽기(ocr_text)로 대조만 하고 화면에는 넣지 않음(CLAUDE.md ④ ①). 목록 제목 줄 뒤에 포스터 줄이 끼어 빈 이름표로 잡히던 것 해소.
select public.ingest_job($ingest${"title": "BĐS Phúc Lộc tuyển giám đốc kinh doanh, chuyên viên kinh doanh dự án Vinhomes Olympic – lương cứng 8–15 triệu/tháng + hoa hồng", "company": "CÔNG TY CỔ PHẦN BẤT ĐỘNG SẢN PHÚC LỘC", "category": "cskh_kinh_doanh", "occupation_code": "3334", "occupation_evidence": "Lộ trình chuyển đổi từ đất nền sang bán đại dự án", "salary": "8.000.000 – 15.000.000đ/tháng", "salary_min": 8000000, "salary_max": 15000000, "salary_period": "month", "location": "Toà B, Chung cư Hoàng Gia 2, số 30 Lạc Long Quân, Kinh Bắc, Bắc Ninh", "employer_phone": "0384873315", "contact_zalo": "0384873315", "num_hires": 30, "description": "[source:facebook] 🔥 ĐẤT NỀN LẮNG SÓNG, TỰ BỎ TIỀN TÚI CHẠY AD MÀ KHÔNG RA KHÁCH?\n👉 CHUYỂN HƯỚNG SANG SIÊU DỰ ÁN VINHOMES OLYMPIC (SVĐ TRỐNG ĐỒNG) CÙNG BĐS PHÚC LỘC NGAY!\nAnh em sale tự do / đất nền đang mệt mỏi vì thị trường trầm lắng? Đừng để bản thân bế tắc! Về đội BĐS Phúc Lộc để đón sóng dòng tiền thực tại Siêu đại đô thị 9.171 ha.\n🌟 CƠ CHẾ \"LẮP TÊN LỬA\" DÀNH CHO BẠN:\n• Lương ổn định: 8 – 15 TRIỆU/tháng ( Hỗ trợ 4 tháng )\n• Đột phá Marketing: Hỗ trợ tới 90% chi phí MKT – Không còn nỗi lo tự chi tiền túi tìm khách.\n• Công cụ hiện đại: Đào tạo & hỗ trợ xây dựng kênh TikTok cá nhân hút nguồn khách nét tự nhiên.\n• Giỏ hàng hot: Độc quyền, đa dạng dòng sản phẩm tại Vinhomes Olympic, cực kỳ dễ thanh khoản.\n• Đào tạo bài bản: Lộ trình chuyển đổi từ đất nền sang bán đại dự án được cầm tay chỉ việc từ A-Z.\n📍 Địa điểm làm việc: Văn phòng Dự án Vinhomes Olympic / Trụ sở BĐS Phúc Lộc.\n📩 CƠ HỘI ĐỔI VẬN – ỨNG TUYỂN NGAY:\n• Hotline / Zalo: 0384 873 315\n• Nhắn tin trực tiếp cho Fanpage để nhận lịch phỏng vấn sớm nhất!\n\nCÔNG TY CỔ PHẦN BẤT ĐỘNG SẢN PHÚC LỘC", "source_text": "🔥 ĐẤT NỀN LẮNG SÓNG, TỰ BỎ TIỀN TÚI CHẠY AD MÀ KHÔNG RA KHÁCH?\n👉 CHUYỂN HƯỚNG SANG SIÊU DỰ ÁN VINHOMES OLYMPIC (SVĐ TRỐNG ĐỒNG) CÙNG BĐS PHÚC LỘC NGAY!\nAnh em sale tự do / đất nền đang mệt mỏi vì thị trường trầm lắng? Đừng để bản thân bế tắc! Về đội